  [431446] = { "Goreのアビリティを得ます：\n\n$I1\nLacerate、Swipe、Maulで対象を攻撃すると、$N1%の確率でMangle (Bear)のクールダウンをリセットし、怒りを$N2得ます。Mangle (Cat)またはShredで対象を攻撃すると、$N3%の確率でTiger's Furyのクールダウンをリセットします。", nil, 0xbf6a19c8, nil, "um" },
