  [431448] = { "Improved Barkskinのアビリティを得ます：\n\n$I1\nBarkskinを味方にもかけられるようになり、近接戦闘の速度や詠唱時間へのペナルティがなくなり、変身中にも詠唱できるようになります。", nil, 0xf905a951, nil, "um" },
  [431449] = { "頭部にImproved Barkskinのルーンを刻みます：\n\n$I1\nBarkskinを味方にも使用できるようになり、近接攻撃速度や詠唱時間へのペナルティがなくなり、変身中でも使用できるようになります。", nil, 0x313924c7, nil, "um" },
  [431450] = { "Gale Windsのアビリティを得ます：\n\n$I1\nHurricaneの与えるダメージが$N1%増加し、クールダウンがなくなり、マナコストが$N2%減少します。", nil, 0x2a12fdde, nil, "um" },
