  [431466] = { "Efflorescenceのアビリティを得ます：\n\n$I1\nSwiftmendがEfflorescenceも発生させるようになり、Swiftmendの対象の位置から$N1ヤード以内のパーティーメンバー全員の体力を、$D2の間、$D1ごとに$N2回復します。", nil, 0xdf1ff38f, nil, "um" },
  [431468] = { "手首にEfflorescenceのルーンを刻みます：\n\n$I1\nSwiftmendがEfflorescenceも発生させるようになり、Swiftmendの対象の位置から$N1ヤード以内のパーティーメンバー全員を、$D2の間$D1ごとに$N2回復します。", nil, 0x666a61dd, nil, "um" },
