  [431601] = { "手首にFocus Fireのルーンを刻みます：\n\n$I1\nペットのFrenzyをすべて消費し、消費したFrenzyごとに、遠隔攻撃速度を$N1%上昇させ、ペットにFocusを$N2与えます。効果時間は$D1です。\n\nペットはBasic Attackを使うたびにFrenzyを得て、$D2の間、近接攻撃速度が$N4%上昇します。最大$N6回までスタックします。", nil, 0x402ff8e0, nil, "um" },
  [431606] = { "$D1の間、ペットの近接攻撃速度を$N1%上昇させます。", "ペットの近接攻撃速度が$N1%上昇します。", 0xc2205de3, 0x389c7132, "uu" },
